            ds.last = { roundScore: rs.score, merch: ds.merchantsHistory[q], vol: ds.volumeHistory[q], ebitda: ds.ebitdaHistory[q],
                        unit: ds.unitHistory[q], fraud: ds.fraudHistory[q], conf: ds.confidenceHistory[q], hard: rs.m.hard };
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            out.merch = ds.last.merch;
            out.vol = ds.last.vol;
            out.ebitda = ds.last.ebitda;
            out.unit = ds.last.unit;
            out.fraud = ds.last.fraud;
            out.conf = ds.last.conf;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, period, g) {
            if (this.ROUND_OF[g] <= period) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _year(dec, k) {
            var c = this.C;
            var per = [];
            var paid = {};
            var m = c.M0;
            var fr = c.FRAUD0;
            var p, i;
            var once = function(key, amount) {
                if (amount && !paid[key]) {
                    paid[key] = true;
                    return amount;
                }
                return 0.0;
            };
            for (p = 1; p <= 4; p++) {
                var a = {};
                for (i = 0; i < this.KEYS.length; i++) { a[this.KEYS[i]] = this._active(dec, p, this.KEYS[i]); }
                var es = this.ESTRUTURA[a.estrutura1];
                var pc = this.PRECO[a.preco1];
                var ky = this.KYC[a.kyc2];
                var ch = this.CANAL[a.canal2];
                var fd = (p >= 3) ? this.FRAUDE[a.fraude3] : this.FRAUDE_NONE;
                var pd = (p >= 3) ? this.PRODUTO[a.produto3] : this.PRODUTO.nada;
                var cu = (p === 4) ? this.CUSTO[a.custo4] : this.CUSTO.manter;
                var mk = (p === 4) ? this.MERCADO[a.mercado4] : this.MERCADO.pme;
                var mkTpv = mk[0], mkQ = mk[2], iMk = mk[6];
                if (a.estrutura1 === 'psti' && a.mercado4 === 'rede' && p === 4) {
                    mkTpv = 0.0; mkQ = 0.0; iMk = 0.0;
                }
                var idxPre = c.IDX0 + es[4] + ky[3] + fd[4] + pd[5] + cu[4] + iMk;
                var nw = ch[0] * pc[2] * ky[1] * cu[3] * mk[3];
                var lote = (p >= 2) ? once('lote', ky[4]) : 0.0;
                if (p === 3 && fd[2] > 0) { fr = fr * (1.0 - fd[2]); }
                var frNew = (nw * ky[2] + lote * this.LOTE_FRAUD) * fd[3] * cu[5];
                var cut = (p === 4 && a.custo4 === 'cortar') ? this.CUT_RET : 0.0;
                var ret = this._clamp(c.RET0 + pc[3] + ch[2] + fd[6] + pd[3] + cut, 0.0, 0.99);
                var mNew = m * ret + nw + lote;
                fr = fr * c.FR_KEEP + frNew;
                var tpvM = c.TPV0 * pd[2] * mk[5];
                var tpv = (mNew - fr) * tpvM * es[5] + mkTpv;
                var loss = fr * c.FRAUD_LOSS * fd[5];
                var frate = (tpv > 0) ? loss / tpv : 0.0;
                var idx = this._clamp(idxPre - 2.0 * Math.max(0.0, frate * 1000.0 - 1.0), 0.0, 100.0);
                var pcost = (a.estrutura1 === 'licenca' && p >= this.AUTH_Q) ? es[1] : es[0];
                var smb = tpv - mkTpv;
                var card = (a.produto3 === 'cartao' && p >= 3) ? this.CARD_NET * this.CARD_SHARE * smb : 0.0;
                var plano = (a.preco1 === 'plano') ? this.PLANO_FEE * 3.0 * (mNew - fr) : 0.0;
                var rev = smb * pc[0] + plano + card + mkTpv * mk[1] + tpv * pc[1] + smb * pd[4];
                var vr = tpv * pcost + mNew * c.SUPPORT * cu[2] + loss + smb * mk[4];
                var acq = nw * (ch[1] + ky[0]) + lote * ky[0];
                var fixed = c.FIXED + cu[1] + es[2] + fd[1] + pd[1] + mkQ + once('e', es[3]) + once('f', fd[0])
                    + once('pr', pd[0]) + once('cu', cu[0]);
                var ebitda = rev - vr - acq - fixed;
                var unit = (rev - vr) / mNew;
                var hard = 0;
                for (i = 0; i < this.HARD.length; i++) {
                    if (a[this.HARD[i][0]] === this.HARD[i][1] && !(this.HARD[i][0] === 'kyc2' && p < 2)) { hard += 1; }
                }
                per.push({ m: mNew, tpv: tpv, ebitda: ebitda, unit: unit, loss: loss, frate: frate, idx: idx, fr: fr,
                           hard: hard, a: a });
                m = mNew;
                if (p >= k) { break; }
            }
            var last = per[per.length - 1];
            return { per: per, ebitda: last.ebitda, unit: last.unit, m: last.m, frate: last.frate, idx: last.idx,
                     tpv: last.tpv, hard: last.hard, a: last.a };
        }

        _components(r) {
            var c = this.C;
            var e = this._clamp((r.ebitda - c.E_LO) / (c.E_HI - c.E_LO), 0, 1);
            var u = this._clamp((r.unit - c.U_LO) / (c.U_HI - c.U_LO), 0, 1);
            var mm = this._clamp((r.m - c.M_LO) / (c.M_HI - c.M_LO), 0, 1);
            var f = this._clamp((c.F_LO - r.frate) / (c.F_LO - c.F_HI), 0, 1);
            var ix = this._clamp((r.idx - c.R_LO) / (c.R_HI - c.R_LO), 0, 1);
            return [e, u, mm, f, ix];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._year(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_E, c.W_U, c.W_M, c.W_F, c.W_R];
            var tw = 0, num = 0, i;
            for (i = 0; i < 5; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'pt';
        }

        _latin() {
            return this._lang() !== 'en';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = this._latin() ? '.' : ',';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + (this._latin() ? ',' : '.') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _fmtPct(n) {
            return (this._lang() === 'es') ? (this._fmtDec(n) + ' %') : (this._fmtDec(n) + '%');
        }

        _fmtBrl(n) {
            if (this._latin()) { return (n < 0 ? '-R$ ' : 'R$ ') + this._fmtInt(Math.abs(n)); }
            return (n < 0 ? '-R$' : 'R$') + this._fmtInt(Math.abs(n));
        }

        _fmtPct3(n) {
            var v = Math.round(Math.abs(n) * 1000);
            var whole = Math.floor(v / 1000);
            var frac = String(v - whole * 1000);
            while (frac.length < 3) { frac = '0' + frac; }
            var txt = String(whole) + (this._latin() ? ',' : '.') + frac;
            txt = (n < 0 ? '-' : '') + txt;
            return (this._lang() === 'es') ? (txt + ' %') : (txt + '%');
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var mH = ds.merchantsHistory || [];
            var vH = ds.volumeHistory || [];
            var eH = ds.ebitdaHistory || [];
            var uH = ds.unitHistory || [];
            var fH = ds.fraudHistory || [];
            var cH = ds.confidenceHistory || [];
            var n = mH.length;
            this._set('merchDisplay', n ? this._fmtInt(mH[n - 1]) : '-');
            this._set('volDisplay', n ? this._fmtBrl(vH[n - 1]) : '-');
            this._set('ebitdaDisplay', n ? (this._fmtBrl(eH[n - 1]) + ' · ' + this._t('txt_year') + ' ' + this._fmtBrl(this._sum(eH))) : '-');
            this._set('unitDisplay', n ? this._fmtBrl(uH[n - 1]) : '-');
            this._set('fraudDisplay', n ? this._fmtPct3(fH[n - 1]) : '-');
            this._set('confDisplay', n ? this._fmtDec(cH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var maps = {
                estrutura1: { baas: 'fb_es_baas', licenca: 'fb_es_licenca', psti: 'fb_es_psti', proprio: 'fb_es_proprio' },
                preco1: { cheio: 'fb_pc_cheio', baixo: 'fb_pc_baixo', plano: 'fb_pc_plano', gratis: 'fb_pc_gratis' },
                kyc2: { leve: 'fb_ky_leve', completo: 'fb_ky_completo', risco: 'fb_ky_risco', lote: 'fb_ky_lote' },
                canal2: { anuncios: 'fb_ca_anuncios', campo: 'fb_ca_campo', contadores: 'fb_ca_contadores', indicacao: 'fb_ca_indicacao' },
                fraude3: { pagar: 'fb_fr_pagar', bloquear: 'fb_fr_bloquear', monitorar: 'fb_fr_monitorar', atrasar: 'fb_fr_atrasar' },
                produto3: { nada: 'fb_pd_nada', automatico: 'fb_pd_automatico', credito: 'fb_pd_credito', cartao: 'fb_pd_cartao' },
                custo4: { manter: 'fb_cu_manter', cortar: 'fb_cu_cortar', automatizar: 'fb_cu_automatizar', terceirizar: 'fb_cu_terceirizar' },
                mercado4: { pme: 'fb_mk_pme', rede: 'fb_mk_rede', cashback: 'fb_mk_cashback', nordeste: 'fb_mk_nordeste' }
            };
            return (maps[g] && maps[g][v]) ? maps[g][v] : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._year(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                confChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Regulatory confidence', data: [], borderColor: '#0f4c5c', backgroundColor: 'rgba(15,76,92,0.12)', borderWidth: 2 },
                            { label: 'Fraud losses (bp)', data: [], borderColor: '#8a4b0c', backgroundColor: 'rgba(138,75,12,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#0f4c5c', backgroundColor: 'rgba(15,76,92,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var confidenceHistory = ds.confidenceHistory || [];
            var fraudHistory = ds.fraudHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = confidenceHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            var bp = fraudHistory.map(function(x) { return Math.round(x * 1000) / 10; });
            return {
                confChart: {
                    labels: labels,
                    datasets: [
                        { data: confidenceHistory.slice(), label: this._t('chart_conf') },
                        { data: bp, label: this._t('chart_fraud') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var dec = function(v) { return self._fmtDec(v); };
            var pct3 = function(v) { return self._fmtPct3(v); };
            var brl = function(v) { return self._fmtBrl(v); };
            var intf = function(v) { return self._fmtInt(v); };
            return [
                { key: 'results.merch', label: 'Active merchants', i18nKey: 'col_merch', formatter: intf },
                { key: 'results.vol', label: 'Pix volume in the quarter', i18nKey: 'col_vol', formatter: brl },
                { key: 'results.ebitda', label: 'EBITDA in the quarter', i18nKey: 'col_ebitda', formatter: brl },
                { key: 'results.unit', label: 'Contribution per merchant', i18nKey: 'col_unit', formatter: brl },
                { key: 'results.fraud', label: 'Fraud losses', i18nKey: 'col_fraud', formatter: pct3 },
                { key: 'results.conf', label: 'Regulatory-confidence index', i18nKey: 'col_conf', formatter: dec },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var m = this._year(this._flat(state, mm), mm);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var d = this._flat(state, mm);
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            var ebitdas = m.per.map(function(x) { return x.ebitda; });
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                ebitda: Math.round(this._sum(ebitdas)),
                merch: Math.round(m.m),
                unit: Math.round(m.unit),
                fraud: Math.round(m.frate * 100000) / 1000,
                conf: Math.round(m.idx * 10) / 10,
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2227-cm">'
                + '<div class="ej2227-cm-score">' + score + '<span class="ej2227-cm-max">/100</span></div>'
                + '<div class="ej2227-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2227-cm-kpis">'
                + '<div class="ej2227-cm-kpi">' + this._t('cm_kpi_ebitda') + ' <strong>' + this._fmtBrl(s.ebitda || 0) + '</strong></div>'
                + '<div class="ej2227-cm-kpi">' + this._t('cm_kpi_merch') + ' <strong>' + this._fmtInt(s.merch || 0) + '</strong></div>'
                + '<div class="ej2227-cm-kpi">' + this._t('cm_kpi_unit') + ' <strong>' + this._fmtBrl(s.unit || 0) + '</strong></div>'
                + '<div class="ej2227-cm-kpi">' + this._t('cm_kpi_fraud') + ' <strong>' + this._fmtPct3(s.fraud || 0) + '</strong></div>'
                + '<div class="ej2227-cm-kpi">' + this._t('cm_kpi_conf') + ' <strong>' + this._fmtDec(s.conf || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2227-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2227-cm-insights">' + items + '</ul>'
                + '</div>';
        }

